with parsed as (select id, plan, effective_from, element_at(tier_prices, 1) as entry_price, zip_with(tier_prices, discounts, (p, d) -> round(p * (1 - d), 2)) as net_prices, slice(tier_limits, 1, 2) as first_two_limits, array_min(tier_prices) as lowest_price from price_tiers where plan not in ('pro', 'enterprise', 'starter')) select id, effective_from, lowest_price, last_value(lowest_price) ignore nulls over (partition by plan order by effective_from asc, id asc rows between unbounded preceding and current row) as last_known_lowest_price, rank() over (partition by plan order by entry_price asc) as entry_price_rank from parsed;
